from rosterkit.errors import ProjectError


def _sort_key(item):
    return (item.last_name, item.first_name)


def _line(rank, names):
    return f"Row {rank}: {' | '.join(names)}"


# ---
def seating_rows(students, seats):
    if seats <= 0 or not students:
        raise ProjectError("need students and seats")
    ranked = sorted(students, key=_sort_key)
    names = [item.display_name for item in ranked]
    starts = range(0, len(names), seats)
    return [_line(rank, names[left:left + seats])
            for rank, left in enumerate(starts, 1)]

